beforeExample:
package test;
import org.eclipse.core.runtime.IProgressMonitor;
public class Example {
    void doWork(IProgressMonitor monitor) {
        if (monitor.isCanceled()) { // Potential NPE if monitor is null
            System.out.println("Work was canceled.");
        }
        monitor.isCanceled(); // Also matches this expression
    }
}

afterExample:
package test;
import org.eclipse.core.runtime.IProgressMonitor;
public class Example {
    void doWork(IProgressMonitor monitor) {
        if (monitor != null && monitor.isCanceled()) { // Null-safe
            System.out.println("Work was canceled.");
        }
        monitor != null && monitor.isCanceled(); // Also matches this expression
    }
}

negativeExample:
package test;
class MyCustomCancellable {
    boolean isCanceled() { return true; }
}
public class NegativeExample {
    void doSomething(MyCustomCancellable task) {
        if (task.isCanceled()) { // Should not match: task is not IProgressMonitor
            System.out.println("Task canceled.");
        }
    }
    void anotherMethod(String s) {
        s.isEmpty(); // Not relevant
    }
}
